  },
};

function createServiceClient(name, overrides = {}) {
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('name must be a non-empty string');
  }
  const client = Object.create(baseClientProto);
  client.name = name;
  const nextHeaders = { ...baseClientProto.defaults.headers };
  if (overrides.header) {
    const [key, value] = overrides.header;
    nextHeaders[key] = value;
  }
  client.defaults = {
    timeoutMs: overrides.timeoutMs ?? baseClientProto.defaults.timeoutMs,
    headers: nextHeaders,
  };
  return client;
}

module.exports = { baseClientProto, createServiceClient };

