problems.solutionCode:
class BaseRegistry {
  constructor(namespace) {
    if (typeof namespace !== 'string' || namespace.trim() === '') {
      throw new TypeError('namespace must be a non-empty string');
    }
    this.namespace = namespace;
    this.entries = Object.create(null);
  }

  set(key, value) {
    if (typeof key !== 'string' || key.trim() === '') {
      throw new TypeError('key must be a non-empty string');
    }
    this.entries[key] = value;
  }

  has(key) {
    return Object.hasOwn(this.entries, key);
  }

  get(key) {
    return this.has(key) ? this.entries[key] : undefined;
  }
}

class ScopedRegistry extends BaseRegistry {
  constructor(namespace, scope) {
    if (typeof scope !== 'string' || scope.trim() === '') {
      throw new TypeError('scope must be a non-empty string');
    }
    super(namespace);
    this.scope = scope;
  }

  get(key) {
    if (!this.has(key)) {
      return undefined;
    }
    return { scope: this.scope, value: super.get(key) };
  }
}

function inspectPrototypeDepth(target) {
  if (target === null || (typeof target !== 'object' && typeof target !== 'function')) {
    return 0;
  }
  let depth = 0;
  let cursor = Object.getPrototypeOf(target);
  while (cursor !== null) {
    depth += 1;
    cursor = Object.getPrototypeOf(cursor);
  }
  return depth;
}

module.exports = { BaseRegistry, ScopedRegistry, inspectPrototypeDepth };

